  {
    return this.evaluateAtLength( this.length * t );
  };

  var evaluateAtLength = function( length, precision )
  {
    var i = 0;

    if ( length < 0 )
    {
      length = 0;
      i = 0;
    }
    else if ( length > this.length )
    {
      length = this.length;
      i = this.curves.length - 1;
    }
    else
    {
      // binary search for the corresponding segment
