      points : points,
      segmentsLength : segmentsLength,
      segmentsPosition : segmentsPosition,
      length : length,
      concat : concat,

      // Curve common
      dimension : points[ 0 ].length,
      evaluateAt : evaluateAt,
      evaluateAtLength : evaluateAtLength,
      getLength : getLength,
      toPolyline : cloneSelf,
      toSpline : toSpline
