							onInit : function ()
							{
								function createLyricAnimation(param)
								{
									var root = newCanvas(param.initalValues);
									var linesRoot = newCanvas({ parent: root });
									var dotsRoot = newCanvas({ parent: root });
									var textCanvas = (newTextBox(
									{
										text: param.text,
										font: param.font,
										initalValues: { parent: root }
									})).canvas;

									var textCanvas2 = (newTextBox(
									{
										text: param.text2,
										font: param.font2,
										initalValues: { parent: root, y: param.upside ? (-param.font2.height - 20) : (param.font.height + 30) }
									})).canvas;

									var circles = [];
									for (var i = 0; i < textCanvas.numChildren; ++i)
									{
										var charShape = textCanvas.getChildAt(param.karaoke[i ^ 0].index);

										var circle = newCanvas({ parent: dotsRoot });
											circle.graphics.beginFill(0x0EFFFF, 0.9);
											circle.graphics.drawCircle(0, 0, 5);
											circle.graphics.endFill();

										circle.x = charShape.x + charShape.width / 2;
										circle.y = charShape.height / 2 + (charShape.height + (charShape.height / 3) * (2 * Math.random() - 1)) * (param.upside ? -1 : 1);
										circles.push(circle);
									}

									var tweens = [];
									for (var i = 0; i < param.karaoke.length; ++i)
									{
										var info = param.karaoke[i ^ 0];
										var charShape = textCanvas.getChildAt(info.index);
										var circle = circles[i ^ 0];

										if (i < param.karaoke.length - 1)
										{
											var nextCircle = circles[i + 1];

											var line = newCanvas({ parent: linesRoot, x: circle.x, y: circle.y});
												rectFill(line, 0, -1, 1, 2, 0xFF184C, 0.7);
											line.rotation = angelBetween(circle.x, circle.y, nextCircle.x, nextCircle.y);
											var length = distance(circle.x, circle.y, nextCircle.x, nextCircle.y);

											tweens.push(
												Tween.delay(
													Tween.parallel(
														Tween.tween(
															charShape,
															{ alpha: 1 },
															{ alpha: 0 },
															0.1,
															TweenEasing.Sine.easeOut
														),
														Tween.tween(
															circle,
															{ alpha: 1 },
															{ alpha: 0 },
															0.1
														),
														Tween.tween(
															line,
															{ alpha: 1 },
															{ alpha: 0 },
															0.1
														),
														Tween.tween(
															line,
															{ scaleX: length },
															{ scaleX: 1 },
															info.delay,
															TweenEasing.Sine.easeOut
														)
													),
													info.startTime
												)
											);
										}
										else
										{
											tweens.push(
												Tween.delay(
													Tween.parallel(
														Tween.tween(
															charShape,
															{ alpha: 1 },
															{ alpha: 0 },
															0.1
														),
														Tween.tween(
															circle,
															{ alpha: 1 },
															{ alpha: 0 },
															0.15
														)
													),
													info.startTime
												)
											);
										}
									}

									return Tween.parallel(
										Tween.parallel.apply(null, tweens),
										Tween.delay(
											Tween.tween(
												textCanvas2,
												{ alpha: 1 },
												{ alpha: 0 },
												0.2
											),
											param.karaoke[0].startTime
										)
									);
								}

								var root = this.pushDisplayObject(newCanvas({ parent: stageCanvas }));
								var mask01 = makeCentered(loadResource('mask_02'), root);
								var lyricLayer = newCanvas({ parent: root });

								mask01.x = 475;
								mask01.y = 271;


								var lyricTween = createLyricAnimation(
								{
									text: 'たくさんの点は線になって',
									font: font_EPMarugo,
									text2: '將許多的點連成線',
									font2: font_MYuppyHKS,
									upside: true,
									initalValues: { parent: lyricLayer, x: 50, y: 150, scaleX: 1.6, scaleY: 1.6 },
									karaoke:
									[
										{ index: 0, startTime: 0.090, delay: 0.210 },
										{ index: 1, startTime: 0.300, delay: 0.200 },
										{ index: 2, startTime: 0.500, delay: 0.220 },
										{ index: 3, startTime: 0.720, delay: 0.220 },
										{ index: 4, startTime: 0.940, delay: 0.240 },
										{ index: 5, startTime: 1.180, delay: 0.400 },
										{ index: 6, startTime: 1.580, delay: 0.220 },
										{ index: 7, startTime: 1.800, delay: 0.450 },
										{ index: 8, startTime: 2.250, delay: 0.430 },
										{ index: 9, startTime: 2.680, delay: 0.230 },
										{ index: 10, startTime: 2.910, delay: 0.200 },
										{ index: 11, startTime: 3.110, delay: 0.470 },
