									text2: '響徹遙遠的彼方',
									font2: font_MYuppyHKS,
									upside: false,
									initalValues: { parent: lyricLayer, x: 450, y: 350, scaleX: 1.6, scaleY: 1.6 },
									karaoke:
									[
										{ index: 0, startTime: 0.000, delay: 0.440 },
