						  else
						  {
							bs = di( t4 - 3, c4, c1 );
						  }

						  if ( f % 2 === 0 )
						  {
							bs[ 1 ] += 15;
						  }

						  return Color.rgbToTransformTint( Color.labToRgb( bs ) );
						};
					  }()
