var startY = _startY;//绘制图形开始点的y坐标
var a_radius = 280;
var b_radius =2;
            g.lineStyle(0,0xffffff);
            for (var i=0; i<360; i++)
            {
                var rad = i * Math.PI / 180;
                var x1=startX+(a_radius+b_radius)*Math.cos(rad)-a_radius*Math.cos((a_radius+b_radius)*rad/b_radius);
                var y1=startY+(a_radius+b_radius)*Math.sin(rad)-a_radius*Math.sin((a_radius+b_radius)*rad/b_radius);
                if (i==0)
                {
                    g.moveTo(x1,y1);
                }
                g.lineTo(x1,y1);
            }

  }
